
const DATA={"lessons": [{"title": "weil, dass & obwohl", "cat": "Grammar", "rule": "Subordinate clauses send the conjugated verb to the end. Use weil for a reason, dass for reported content, and obwohl for a contrast. Separate the clauses with a comma.", "example": "Ich lerne Deutsch, weil ich in Zürich arbeite.", "translation": "I am learning German because I work in Zurich.", "questions": [{"q": "Ich bleibe zu Hause, weil ich krank ___.", "options": ["bin", "ist", "sein"], "answer": 0, "why": "The subject ich takes bin. The verb goes at the end of the weil clause."}, {"q": "___ es regnet, gehen wir spazieren.", "options": ["Weil", "Obwohl", "Dass"], "answer": 1, "why": "Obwohl expresses contrast: we go for a walk although it is raining."}, {"q": "Ich glaube, dass er morgen ___.", "options": ["kommt", "kommen", "kommst"], "answer": 0, "why": "Er takes kommt, placed at the end of the dass clause."}, {"q": "Ich nehme einen Schirm mit, ___ es regnet.", "options": ["deshalb", "weil", "trotzdem", "denn"], "answer": 1, "why": "The rain is the reason; the verb is final."}, {"q": "Ich hoffe, ___ du bald gesund wirst.", "options": ["dass", "als", "weil", "ob"], "answer": 0, "why": "Dass introduces the content of the hope."}, {"q": "___ ich gestern ankam, war es schon dunkel.", "options": ["Damit", "Wenn", "Als", "Ob"], "answer": 2, "why": "A single event in the past uses als."}, {"q": "Wir gehen spazieren, ___ es regnet.", "options": ["deshalb", "denn", "trotzdem", "obwohl"], "answer": 3, "why": "Walking despite rain expresses contrast."}, {"q": "Ich rufe dich an, ___ ich losfahre.", "options": ["trotzdem", "deshalb", "bevor", "denn"], "answer": 2, "why": "The call comes before departure."}, {"q": "Sie erklärt es langsam, ___ alle sie verstehen.", "options": ["um", "deshalb", "denn", "damit"], "answer": 3, "why": "Damit expresses purpose with a finite clause."}], "group": "Sentence structure", "guide": {"steps": ["Decide the relationship: a reason (weil), content (dass), or an unexpected contrast (obwohl).", "Write the main clause normally. Put a comma before the subordinate clause.", "Move the conjugated verb to the very end of the subordinate clause."], "examples": [["Ich bleibe zu Hause, weil ich krank bin.", "Reason: I stay home because I am ill."], ["Obwohl ich krank bin, gehe ich zur Arbeit.", "Contrast: although I am ill, I go to work. The whole subordinate clause occupies position one; gehe follows it."]], "trap": "Do not use main-clause order after weil: weil ich bin krank is not the standard written pattern."}}, {"title": "Relative clauses", "cat": "Grammar", "rule": "A relative clause describes a noun. Its verb goes last. Gender and number come from the noun; the case comes from the pronoun’s role inside the relative clause. Dative plural uses denen.", "example": "Das ist der Mann, dem ich geholfen habe.", "translation": "That is the man whom I helped.", "questions": [{"q": "Die Frau, ___ hier wohnt, ist Ärztin.", "options": ["der", "die", "den"], "answer": 1, "why": "Frau is feminine and the relative pronoun is the subject: die."}, {"q": "Das ist der Film, ___ ich gesehen habe.", "options": ["der", "dem", "den"], "answer": 2, "why": "Film is masculine and is the object of gesehen: accusative den."}, {"q": "Die Leute, mit ___ ich arbeite, sind nett.", "options": ["denen", "die", "deren"], "answer": 0, "why": "Mit requires dative. The dative plural relative pronoun is denen."}, {"q": "Das ist der Mann, ___ hier wohnt.", "options": ["den", "dem", "der", "dessen"], "answer": 2, "why": "Masculine nominative subject: der."}, {"q": "Das ist das Kind, ___ ich helfe.", "options": ["den", "dessen", "das", "dem"], "answer": 3, "why": "Helfen requires dative; neuter dative is dem."}, {"q": "Die Leute, mit ___ wir sprechen, sind nett.", "options": ["den", "die", "deren", "denen"], "answer": 3, "why": "Mit requires dative; the plural relative pronoun is denen."}, {"q": "Der Film, ___ wir anschauen, ist spannend.", "options": ["den", "dem", "dessen", "der"], "answer": 0, "why": "Film is masculine and the object of anschauen."}, {"q": "Die Frau, ___ Tochter Ärztin ist, wohnt hier.", "options": ["dessen", "deren", "der", "die"], "answer": 1, "why": "Feminine genitive relative pronoun: deren Tochter."}, {"q": "Das ist die Stadt, in ___ ich geboren bin.", "options": ["der", "die", "den", "dem"], "answer": 0, "why": "A fixed location in a feminine noun uses dative der."}], "group": "Pronouns", "guide": {"steps": ["Identify the noun you are describing and its gender/number.", "Ask what the relative pronoun does inside its own clause: subject, object, recipient, or object of a preposition.", "Choose the case, add commas, and put the relative-clause verb last."], "examples": [["Der Mann, der hier wohnt, heißt Ali.", "Der is the subject of wohnt: masculine nominative."], ["Der Mann, den ich kenne, heißt Ali.", "Ich is the subject; the man is the object of kenne: masculine accusative den."]], "trap": "The article before the original noun does not automatically determine the case inside the relative clause."}}, {"title": "Konjunktiv II: wishes & politeness", "cat": "Grammar", "rule": "Use würde + infinitive for many hypothetical actions. Common forms include hätte (haben), wäre (sein), and könnte (können). These forms also make requests more polite.", "example": "Wenn ich mehr Zeit hätte, würde ich öfter lesen.", "translation": "If I had more time, I would read more often.", "questions": [{"q": "___ Sie mir bitte helfen?", "options": ["Könnten", "Können würde", "Könntest"], "answer": 0, "why": "Könnten Sie is a polite request with formal Sie."}, {"q": "Wenn ich reich ___, würde ich reisen.", "options": ["bin", "wäre", "war"], "answer": 1, "why": "An unreal condition uses wäre."}, {"q": "Ich würde gern in Berlin ___.", "options": ["wohne", "wohnen", "gewohnt"], "answer": 1, "why": "Würde combines with an infinitive at the end."}, {"q": "Wenn ich mehr Zeit ___, würde ich reisen.", "options": ["habe", "hatte", "hätte", "hat"], "answer": 2, "why": "An unreal condition with haben takes hätte."}, {"q": "Ich ___ gern einen Tee.", "options": ["hätte", "hätten", "hatte", "habe gehabt"], "answer": 0, "why": "Hätte gern is a polite expression of a wish."}, {"q": "Wir würden gern in Wien ___.", "options": ["wohnten", "gewohnt", "wohnt", "wohnen"], "answer": 3, "why": "Würde combines with an infinitive."}, {"q": "___ du mir helfen?", "options": ["Könntest", "Könnte", "Können", "Könnten"], "answer": 0, "why": "The polite request addressed to du uses könntest."}, {"q": "An deiner Stelle ___ ich früher anfangen.", "options": ["werde werden", "würdest", "würden", "würde"], "answer": 3, "why": "An deiner Stelle expresses hypothetical advice."}, {"q": "___ es möglich, den Termin zu ändern?", "options": ["Wäre", "Waren", "Wären", "Wärst"], "answer": 0, "why": "Wäre es möglich ...? is a polite request pattern."}], "group": "Verbs", "guide": {"steps": ["Choose the purpose: a polite request, a wish, advice or an unreal condition.", "Use the common special forms hätte, wäre and könnte; for many other verbs use würde + infinitive.", "With würde, leave the main verb as an infinitive at the end. In a wenn clause, put the finite verb last."], "examples": [["Ich hätte gern einen Kaffee.", "A polite wish: I would like a coffee."], ["Wenn ich Zeit hätte, würde ich mitkommen.", "Unreal condition: if I had time, I would come along."]], "trap": "Konnte is past ability; könnte expresses possibility or a polite/hypothetical meaning."}}, {"title": "Passive voice", "cat": "Grammar", "rule": "The process passive focuses on an action: werden + past participle. The form of werden changes with the subject and tense. The agent can be introduced with von + dative.", "example": "Die Fahrräder werden in der Werkstatt repariert.", "translation": "The bicycles are being repaired in the workshop.", "questions": [{"q": "Das Paket ___ morgen geliefert.", "options": ["wird", "werden", "hat"], "answer": 0, "why": "Das Paket is singular, so use wird + geliefert."}, {"q": "Die Fenster werden ___.", "options": ["putzen", "geputzt", "geputzen"], "answer": 1, "why": "The passive needs the past participle geputzt."}, {"q": "Der Brief ___ gestern geschrieben.", "options": ["wird", "wurde", "werden"], "answer": 1, "why": "Gestern calls for a past form here: wurde geschrieben."}, {"q": "Die Briefe ___ jeden Morgen sortiert.", "options": ["wird", "werden", "hat"], "answer": 1, "why": "The plural subject takes werden; sortiert is the participle."}, {"q": "Das Fenster wurde gestern ___.", "options": ["reparieren", "reparierte", "repariert"], "answer": 2, "why": "Passive uses werden plus a past participle, here repariert."}, {"q": "Der Kuchen wird von ___ Mutter gebacken.", "options": ["meine", "meiner", "meinen"], "answer": 1, "why": "The agent is introduced by von + dative: meiner Mutter."}, {"q": "Aktiv: Man öffnet die Tür. Passiv: Die Tür ___.", "options": ["wird geöffnet", "hat geöffnet", "ist öffnen"], "answer": 0, "why": "The action passive is wird geöffnet."}, {"q": "Die Wohnung ___ letzte Woche renoviert.", "options": ["werden", "wurde", "wird"], "answer": 1, "why": "Letzte Woche refers to the past, so use wurde."}, {"q": "Was steht im Passiv im Vordergrund?", "options": ["Wer etwas besitzt", "Die Handlung bzw. das Geschehen", "Ein Wunsch"], "answer": 1, "why": "The passive focuses on what happens rather than who performs the action."}], "group": "Verbs", "guide": {"steps": ["Find the thing affected by the action; make it the subject.", "Conjugate werden for that subject and tense.", "Put the past participle at the end. Add von + dative only if the performer matters."], "examples": [["Der Mechaniker repariert das Auto. → Das Auto wird repariert.", "The object becomes the passive subject."], ["Die Autos wurden gestern repariert.", "Plural and past tense require wurden."]], "trap": "Process passive uses werden. Das Auto ist repariert describes a resulting state, not the same grammatical construction."}}, {"title": "Past tenses in everyday stories", "cat": "Grammar", "rule": "In conversation, use Perfekt for many completed events. Movement to a destination often takes sein; most other verbs take haben. Sein, haben and modal verbs commonly use Präteritum. Plusquamperfekt describes an earlier past event.", "example": "Nachdem ich gegessen hatte, bin ich zum Kurs gefahren.", "translation": "After I had eaten, I went to the course.", "questions": [{"q": "Gestern ___ wir nach Bern gefahren.", "options": ["haben", "sind", "werden"], "answer": 1, "why": "Fahren with a destination uses sein in the Perfekt."}, {"q": "Ich ___ gestern keine Zeit.", "options": ["hatte", "hätte", "haben"], "answer": 0, "why": "Hatte is the Präteritum of haben."}, {"q": "Als er ankam, ___ ich schon gekocht.", "options": ["habe", "hatte", "bin"], "answer": 1, "why": "Cooking happened before his arrival: hatte gekocht."}, {"q": "Gestern ___ ich nach Basel gefahren.", "options": ["habe", "bin", "werde", "hatte"], "answer": 1, "why": "Movement to a destination with fahren uses sein."}, {"q": "Sie ___ früher in Bonn.", "options": ["sein", "war", "bin", "waren"], "answer": 1, "why": "War is the singular Präteritum of sein."}, {"q": "Wir ___ gestern viel Arbeit.", "options": ["haben gehabt sein", "hatten", "hättet", "hatte"], "answer": 1, "why": "Wir takes hatten in Präteritum."}, {"q": "Er ___ nicht schlafen, weil es laut war.", "options": ["konnte", "kannst", "könnte", "können"], "answer": 0, "why": "Konnte is past ability; könnte would be hypothetical."}, {"q": "Ich ___ gestern zu Hause geblieben.", "options": ["habe", "werde", "bin", "hatte"], "answer": 2, "why": "Bleiben uses sein in Perfekt."}, {"q": "Nachdem ich gegessen ___, ging ich zur Arbeit.", "options": ["bin", "war", "hatte", "habe"], "answer": 2, "why": "The earlier past action uses Plusquamperfekt hatte gegessen."}], "group": "Tenses", "guide": {"steps": ["Put the events in order: what happened first, and what happened later?", "For ordinary spoken events, use Perfekt; use common Präteritum forms such as war, hatte and konnte naturally.", "For something already completed before another past event, use hatte/war + past participle."], "examples": [["Ich war müde und bin früh nach Hause gegangen.", "A common combination of Präteritum sein and Perfekt gehen."], ["Ich hatte gegessen, bevor ich losging.", "The eating happened before leaving."]], "trap": "Do not choose a tense only because English uses one: pay attention to the German auxiliary and event order."}}, {"title": "Adjective endings", "cat": "Grammar", "rule": "Adjectives before nouns take endings. After a definite article, use -e in nominative singular and accusative feminine/neuter; most other forms take -en. After ein, the adjective may need to show gender itself.", "example": "Ich suche eine ruhige Wohnung mit einem kleinen Balkon.", "translation": "I am looking for a quiet flat with a small balcony.", "questions": [{"q": "Ich kaufe den rot___ Mantel.", "options": ["e", "en", "er"], "answer": 1, "why": "After den in masculine accusative, the adjective takes -en."}, {"q": "Das ist ein schön___ Haus.", "options": ["es", "e", "en"], "answer": 0, "why": "Ein does not show neuter gender here; schönes supplies the ending."}, {"q": "Mit einer nett___ Kollegin lerne ich Deutsch.", "options": ["e", "er", "en"], "answer": 2, "why": "After einer in dative feminine, use netten."}, {"q": "Das ist ein schön___ Haus.", "options": ["en", "er", "es", "e"], "answer": 2, "why": "Ein does not mark neuter here, so schönes supplies the marker."}, {"q": "Die neu___ Kollegin kommt heute.", "options": ["er", "es", "e", "en"], "answer": 2, "why": "Feminine nominative after die takes -e."}, {"q": "Mit einem gut___ Freund geht alles leichter.", "options": ["es", "e", "er", "en"], "answer": 3, "why": "After einem in dative, use -en."}, {"q": "Ich trinke kalt___ Wasser.", "options": ["e", "en", "er", "es"], "answer": 3, "why": "Without an article, neuter accusative takes strong -es."}, {"q": "Ein klein___ Hund bellt.", "options": ["en", "es", "e", "er"], "answer": 3, "why": "Masculine nominative after ein takes -er."}, {"q": "Ich helfe den neu___ Nachbarn.", "options": ["en", "es", "e", "er"], "answer": 0, "why": "Plural dative after den takes -en."}], "group": "Adjectives", "guide": {"steps": ["Find the noun’s gender, number and case.", "Look at the article: definite (der), ein-type (ein/mein/kein), or no article.", "Choose the adjective ending that supplies the remaining grammatical information."], "examples": [["der kleine Hund → mit dem kleinen Hund", "The dative after mit changes the adjective to -en."], ["ein kleines Haus → das kleine Haus", "Ein does not show the neuter marker here, so kleines supplies it."]], "trap": "An adjective after sein usually has no ending: Das Haus ist klein, not kleines."}}, {"title": "Two-way prepositions", "cat": "Grammar", "rule": "An, auf, hinter, in, neben, über, unter, vor and zwischen use accusative for a destination and dative for a location. Ask wohin? for a destination and wo? for a location.", "example": "Ich stelle die Tasche auf den Tisch. Sie steht jetzt auf dem Tisch.", "translation": "I put the bag onto the table. It is now on the table.", "questions": [{"q": "Das Bild hängt an ___ Wand.", "options": ["die", "der", "den"], "answer": 1, "why": "A fixed location uses dative: an der Wand."}, {"q": "Ich gehe in ___ Küche.", "options": ["der", "die", "den"], "answer": 1, "why": "The kitchen is the destination: in die Küche."}, {"q": "Wir sitzen auf ___ Balkon.", "options": ["dem", "den", "der"], "answer": 0, "why": "Sitzen describes a location: auf dem Balkon."}, {"q": "Die Katze schläft auf ___ Sofa.", "options": ["das", "dem", "den", "der"], "answer": 1, "why": "A fixed location uses dative; Sofa is neuter."}, {"q": "Das Bild hängt an ___ Wand.", "options": ["dem", "der", "die", "den"], "answer": 1, "why": "The picture is located on the wall: feminine dative."}, {"q": "Die Kinder spielen in ___ Garten.", "options": ["den", "dem", "der", "das"], "answer": 1, "why": "Playing takes place within a location; Garten is masculine dative."}, {"q": "Die Schuhe stehen unter ___ Bett.", "options": ["dem", "der", "das", "den"], "answer": 0, "why": "The bed is a location: neuter dative."}, {"q": "Wir warten vor ___ Kino.", "options": ["das", "dem", "den", "der"], "answer": 1, "why": "Waiting is at a location: neuter dative."}, {"q": "Er stellt den Stuhl neben ___ Tür.", "options": ["die", "der", "dem", "den"], "answer": 0, "why": "The position beside the door is the destination: accusative."}], "group": "Prepositions", "guide": {"steps": ["Check whether the preposition is one of the two-way group.", "Ask whether the phrase describes a location (wo?) or a destination (wohin?).", "Use dative for location and accusative for destination."], "examples": [["Das Buch liegt auf dem Tisch.", "Location: where is it? Dative dem Tisch."], ["Ich lege das Buch auf den Tisch.", "Destination: where do I put it? Accusative den Tisch."]], "trap": "Movement alone does not force accusative: Ich laufe im Park describes movement inside a location."}}, {"title": "Infinitives with zu", "cat": "Grammar", "rule": "Use zu + infinitive after expressions such as versuchen and es ist wichtig. With separable verbs, place zu between prefix and stem. Um ... zu expresses a purpose when both clauses have the same subject; damit can introduce a different subject.", "example": "Ich lerne jeden Tag, um die Prüfung zu bestehen.", "translation": "I study every day in order to pass the exam.", "questions": [{"q": "Ich versuche, früh ___.", "options": ["aufzustehen", "zu aufstehen", "aufstehen zu"], "answer": 0, "why": "The separable verb aufstehen becomes aufzustehen."}, {"q": "Sie spart Geld, ___ ein Fahrrad zu kaufen.", "options": ["damit", "um", "weil"], "answer": 1, "why": "A shared subject and purpose use um ... zu."}, {"q": "Ich spreche langsam, damit du mich besser ___.", "options": ["verstehen", "zu verstehen", "verstehst"], "answer": 2, "why": "Damit introduces a finite subordinate clause: du verstehst."}, {"q": "Es ist wichtig, regelmäßig ___ lernen.", "options": ["zu", "um", "damit"], "answer": 0, "why": "An infinitive after es ist wichtig uses zu."}, {"q": "Ich habe vergessen, dich ___.", "options": ["anzurufen", "zu anrufen", "anrufen zu"], "answer": 0, "why": "In separable anrufen, zu goes between the prefix and stem."}, {"q": "Er spart Geld, um eine Wohnung zu ___.", "options": ["gemietet", "mieten", "mietet"], "answer": 1, "why": "Um ... zu takes an infinitive, mieten."}, {"q": "Wir bleiben zu Hause, ___ die Kinder schlafen können.", "options": ["um", "zu", "damit"], "answer": 2, "why": "Different subjects require a finite purpose clause: damit die Kinder ... können."}, {"q": "Sie versucht, weniger Kaffee ___ trinken.", "options": ["um", "zu", "dass"], "answer": 1, "why": "Versuchen can be followed by zu + infinitive."}, {"q": "Nach einem Modalverb: Ich kann gut ___.", "options": ["zu schwimmen", "schwimmen", "geschwommen"], "answer": 1, "why": "A modal verb takes the bare infinitive without zu."}], "group": "Sentence structure", "guide": {"steps": ["Check whether the first verb/expression takes a zu infinitive.", "For a separable verb, insert zu between prefix and stem.", "For purpose, use um ... zu with the same subject; use damit when a separate finite clause is needed."], "examples": [["Ich versuche, früh aufzustehen.", "Aufstehen → aufzustehen."], ["Ich lerne, um die Prüfung zu bestehen.", "The person studying is also the person who wants to pass."]], "trap": "After modal verbs, do not add zu: Ich kann schwimmen."}}, {"title": "Connectors & word order", "cat": "Grammar", "rule": "Deshalb and trotzdem occupy a position in the main clause; when they come first, the conjugated verb comes second and the subject follows. Weil and obwohl introduce subordinate clauses with the verb at the end.", "example": "Ich bin müde. Trotzdem mache ich meine Hausaufgaben.", "translation": "I am tired. Nevertheless, I am doing my homework.", "questions": [{"q": "Es regnet. Deshalb ___ ich zu Hause.", "options": ["bleibe", "ich bleibe", "bleiben"], "answer": 0, "why": "Deshalb occupies position one; bleibe is position two."}, {"q": "Er ist krank. ___ geht er zur Arbeit.", "options": ["Deshalb", "Trotzdem", "Weil"], "answer": 1, "why": "Going to work despite illness is a contrast: trotzdem."}, {"q": "Ich lerne, ___ ich die Prüfung bestehen möchte.", "options": ["deshalb", "weil", "trotzdem"], "answer": 1, "why": "The verb-final clause is introduced by weil."}, {"q": "Er ist müde. ___ arbeitet er weiter.", "options": ["Dass", "Obwohl", "Trotzdem", "Weil"], "answer": 2, "why": "Continuing despite tiredness is a contrast."}, {"q": "___ ich gestern ankam, war es schon dunkel.", "options": ["Damit", "Wenn", "Als", "Ob"], "answer": 2, "why": "A single event in the past uses als."}, {"q": "Immer ___ ich Zeit habe, lese ich.", "options": ["als", "dass", "wenn", "ob"], "answer": 2, "why": "A repeated situation uses wenn."}, {"q": "Er hat viel gelernt. ___ besteht er die Prüfung.", "options": ["Dass", "Deshalb", "Weil", "Obwohl"], "answer": 1, "why": "The second sentence is a consequence; finite verb in position two."}, {"q": "Ich möchte wissen, ___ der Bus heute fährt.", "options": ["weil", "wenn", "als", "ob"], "answer": 3, "why": "An indirect yes/no question uses ob."}, {"q": "Ich weiß nicht, ___ er ankommt. – Wahrscheinlich um acht.", "options": ["wann", "wenn", "als", "ob"], "answer": 0, "why": "The answer concerns a time: wann."}], "group": "Sentence structure", "guide": {"steps": ["Choose the meaning: reason, consequence or contrast.", "Identify the connector type: weil/obwohl introduce subordinate clauses; deshalb/trotzdem belong to main clauses.", "Check verb position: subordinate-clause end, or position two after deshalb/trotzdem."], "examples": [["Es regnet. Deshalb bleibe ich zu Hause.", "Consequence: Deshalb occupies the first position, then bleibe."], ["Ich bleibe zu Hause, weil es regnet.", "Reason: the subordinate finite verb regnet is last."]], "trap": "Do not write Deshalb ich bleibe ...; the finite verb comes immediately after Deshalb here."}}, {"title": "Verbs with prepositions", "cat": "Grammar", "rule": "Learn fixed combinations together with the required case: warten auf + accusative, teilnehmen an + dative, sich interessieren für + accusative. For things, use worauf/darauf; for people, use auf wen/auf ihn.", "example": "Ich freue mich auf den Urlaub.", "translation": "I am looking forward to the holiday.", "questions": [{"q": "Ich warte ___ den Bus.", "options": ["auf", "für", "an"], "answer": 0, "why": "The fixed combination is warten auf + accusative."}, {"q": "Sie nimmt an ___ Kurs teil.", "options": ["den", "dem", "der"], "answer": 1, "why": "Teilnehmen an requires dative: an dem Kurs."}, {"q": "___ interessierst du dich? – Für Musik.", "options": ["Wofür", "Womit", "Woran"], "answer": 0, "why": "Sich interessieren für becomes wofür when asking about a thing."}, {"q": "Wir nehmen ___ einem Kurs teil.", "options": ["mit", "an", "auf", "für"], "answer": 1, "why": "Teilnehmen an takes dative."}, {"q": "Er erinnert sich ___ den Urlaub.", "options": ["von", "an", "mit", "für"], "answer": 1, "why": "Sich erinnern an takes accusative."}, {"q": "Ich bitte dich ___ Hilfe.", "options": ["an", "um", "mit", "von"], "answer": 1, "why": "Jemanden um etwas bitten uses um + accusative."}, {"q": "Sie träumt ___ einer Reise.", "options": ["auf", "von", "für", "an"], "answer": 1, "why": "Träumen von takes dative."}, {"q": "Er entschuldigt sich ___ seiner Kollegin.", "options": ["an", "auf", "bei", "für"], "answer": 2, "why": "Sich bei einer Person entschuldigen names the person."}, {"q": "Es hängt ___ dem Wetter ab.", "options": ["um", "an", "für", "von"], "answer": 3, "why": "Abhängen von takes dative and means to depend on."}], "group": "Prepositions", "guide": {"steps": ["Learn the whole unit: verb + preposition + case.", "Choose the correct article/pronoun after that fixed preposition.", "When asking about things, use wo(r)+preposition; for people use preposition + wen/wem."], "examples": [["Ich warte auf den Bus. → Worauf wartest du?", "Warten auf + accusative; a thing becomes worauf."], ["Ich spreche mit meiner Kollegin. → Mit wem sprichst du?", "A person after mit requires wem."]], "trap": "Do not translate the preposition directly from your first language; the German verb determines the combination."}}, {"title": "A new start in Leipzig", "cat": "Reading", "rule": "Read for the main idea first, then find evidence for each answer. You do not need to translate every word.", "example": "Seit drei Monaten wohnt Sara in Leipzig. Früher fuhr sie mit dem Auto zur Arbeit. Jetzt nimmt sie die Straßenbahn, weil sie Geld sparen möchte. Ihre neue Wohnung ist kleiner als die alte, aber sie liegt näher am Büro. Am Samstag trifft Sara ihre Nachbarin im Park. Zusammen wollen sie einen Sprachkurs suchen. Sara spricht schon gut Deutsch, möchte aber beim Telefonieren sicherer werden.", "translation": "Sara moved to Leipzig three months ago. She now travels by tram to save money. Her smaller flat is closer to work. She and her neighbour plan to find a language course so Sara can feel more confident on the phone.", "questions": [{"q": "Warum fährt Sara mit der Straßenbahn?", "options": ["Sie möchte Geld sparen.", "Ihr Auto ist kaputt.", "Sie arbeitet im Park."], "answer": 0, "why": "The text states: weil sie Geld sparen möchte."}, {"q": "Was ist ein Vorteil der neuen Wohnung?", "options": ["Sie ist größer.", "Sie liegt näher am Büro.", "Sie kostet nichts."], "answer": 1, "why": "The flat is smaller, but closer to the office."}, {"q": "Was möchte Sara verbessern?", "options": ["Kochen", "Autofahren", "Telefonieren auf Deutsch"], "answer": 2, "why": "She wants to feel more confident when making phone calls."}], "group": "Everyday life"}, {"title": "An appointment change", "cat": "Listening", "rule": "Listen before revealing the transcript. The audio uses your browser’s German text-to-speech voice, when available. Listen for the date, time and action you need to take.", "example": "Guten Tag, Frau Keller. Hier ist die Praxis von Dr. Braun. Leider müssen wir Ihren Termin am Dienstag verschieben, weil die Ärztin krank ist. Wir können Ihnen stattdessen einen Termin am Donnerstag um vierzehn Uhr dreißig anbieten. Bitte rufen Sie uns bis morgen Mittag zurück. Bringen Sie zum Termin Ihre Versicherungskarte und die Liste Ihrer Medikamente mit. Vielen Dank.", "translation": "The practice needs to move Tuesday’s appointment because the doctor is ill. They offer Thursday at 2:30 pm. Mrs Keller should call back by tomorrow noon and bring her insurance card and medication list.", "questions": [{"q": "Wann ist der neue Termin?", "options": ["Dienstag um 14:30", "Donnerstag um 14:30", "Donnerstag um 16:30"], "answer": 1, "why": "The message offers Donnerstag um vierzehn Uhr dreißig."}, {"q": "Bis wann soll Frau Keller zurückrufen?", "options": ["Bis heute Abend", "Bis nächste Woche", "Bis morgen Mittag"], "answer": 2, "why": "The deadline is tomorrow at noon."}, {"q": "Was soll sie mitbringen?", "options": ["Versicherungskarte und Medikamentenliste", "Reisepass und Foto", "Nur Bargeld"], "answer": 0, "why": "The message asks for the insurance card and a list of medications."}], "group": "Appointments"}, {"title": "Present tense & separable verbs", "cat": "Grammar", "group": "Tenses", "rule": "In a main clause, the conjugated verb is in second position. Separable prefixes move to the end. In a subordinate clause, the prefix stays attached. Watch stem changes such as fahren → du fährst and lesen → er liest.", "example": "Der Kurs fängt um neun an. Ich weiß, dass er um neun anfängt.", "translation": "The course starts at nine. I know that it starts at nine.", "questions": [{"q": "Wann ___ der Unterricht an?", "options": ["fangen", "fängt", "fängst"], "answer": 1, "why": "Unterricht is singular: er fängt an."}, {"q": "Ich weiß, dass sie früh ___.", "options": ["aufsteht", "steht auf", "aufstehen"], "answer": 0, "why": "A separable verb stays together at the end of a subordinate clause."}, {"q": "Er ___ jeden Abend die Zeitung.", "options": ["lese", "lesen", "liest"], "answer": 2, "why": "Lesen changes its stem in the third-person singular: er liest."}, {"q": "Du ___ jeden Tag mit dem Zug.", "options": ["fährst", "fahrt", "fahren"], "answer": 0, "why": "Fahren changes its stem with du: du fährst."}, {"q": "Wir ___ morgen früh auf.", "options": ["stehen", "steht", "stehe"], "answer": 0, "why": "Wir takes stehen; the separable prefix auf comes at the end."}, {"q": "Er ___ die Tür zu.", "options": ["machen", "machst", "macht"], "answer": 2, "why": "Er takes macht; zumachen separates in a main clause."}, {"q": "Ich weiß, dass der Zug bald ___.", "options": ["ab fährt", "abfährt", "fährt ab"], "answer": 1, "why": "In a subordinate clause, the separable verb stays together at the end."}, {"q": "Ihr ___ sehr schnell.", "options": ["spricht", "sprechen", "sprecht"], "answer": 2, "why": "The ihr form is sprecht; the stem change applies to du and er/sie/es."}, {"q": "Am Samstag ___ ich meine Freundin.", "options": ["besuche", "ich besuche", "besuchen"], "answer": 0, "why": "After the opening time expression, the finite verb stays in position two."}], "guide": {"steps": ["Find the subject and choose the present-tense ending.", "Check whether the verb changes its stem with du or er/sie/es.", "In a main clause, send a separable prefix to the end; in a subordinate clause, keep the verb together."], "examples": [["Du fährst mit dem Zug.", "Fahren changes a → ä with du."], ["Ich stehe auf. / Ich weiß, dass ich früh aufstehe.", "The same separable verb behaves differently in a main and subordinate clause."]], "trap": "A time expression can occupy position one: Morgen stehe ich früh auf, not Morgen ich stehe ..."}}, {"title": "Perfekt: haben or sein?", "cat": "Grammar", "group": "Tenses", "rule": "Build the Perfekt with haben or sein in the present tense and a past participle. Most verbs use haben. Many intransitive verbs describing a change of location or state use sein, as do bleiben and sein. Learn irregular participles with their verbs.", "example": "Wir sind angekommen und haben unsere Freunde besucht.", "translation": "We arrived and visited our friends.", "questions": [{"q": "Sie ___ gestern eingeschlafen.", "options": ["hat", "ist", "wird"], "answer": 1, "why": "Einschlafen describes a change of state and uses sein."}, {"q": "Ich habe meine Freundin ___.", "options": ["besuchen", "gebesucht", "besucht"], "answer": 2, "why": "The inseparable prefix be- prevents an extra ge-."}, {"q": "Wir ___ den Film gesehen.", "options": ["haben", "sind", "werden"], "answer": 0, "why": "Sehen takes haben: wir haben gesehen."}, {"q": "Gestern ___ ich nach Basel gefahren.", "options": ["habe", "bin", "werde", "hatte"], "answer": 1, "why": "Movement to a destination with fahren uses sein."}, {"q": "Wir haben einen Film ___.", "options": ["sah", "gesehen", "geseht", "sehen"], "answer": 1, "why": "The past participle of sehen is gesehen."}, {"q": "Ich habe die Rechnung ___.", "options": ["bezahlte", "gebezahlt", "bezahlt", "bezahlen"], "answer": 2, "why": "Bezahlen has inseparable be- and no additional ge-."}, {"q": "Der Zug ist pünktlich ___.", "options": ["ankommen", "angekommen", "ankam", "angekommt"], "answer": 1, "why": "Ankommen forms the participle angekommen and uses sein."}, {"q": "Sie hat die Tür ___.", "options": ["öffnete", "öffnen", "geöffnet", "geöffnen"], "answer": 2, "why": "Öffnen forms the participle geöffnet."}, {"q": "Wir haben unsere Freunde ___.", "options": ["besuchte", "gebesucht", "besuchen", "besucht"], "answer": 3, "why": "Besuchen has no ge- because of inseparable be-."}], "guide": {"steps": ["Choose the auxiliary: most verbs use haben; common intransitive changes of place/state use sein.", "Conjugate the auxiliary in the present tense.", "Build or recall the past participle and put it at the end."], "examples": [["Ich habe einen Film gesehen.", "Sehen takes haben and the irregular participle gesehen."], ["Wir sind nach Hause gefahren.", "A journey to a destination uses sein here."]], "trap": "Do not add ge- to verbs with inseparable be-, ver- or er-: besucht, verstanden, erzählt."}}, {"title": "Präteritum: common irregular verbs", "cat": "Grammar", "group": "Tenses", "rule": "Präteritum is common in written stories. It is also common in conversation for sein, haben and modal verbs. Strong verbs change their stem. Ich and er/sie/es usually have no added ending in strong-verb Präteritum.", "example": "Als Kind war ich oft bei meiner Oma. Sie las mir Geschichten vor.", "translation": "As a child I often stayed with my grandma. She read stories to me.", "questions": [{"q": "Früher ___ wir auf dem Land.", "options": ["waren", "war", "wären"], "answer": 0, "why": "Wir takes waren in the Präteritum of sein."}, {"q": "Er ___ gestern nicht kommen.", "options": ["können", "konnte", "könnte"], "answer": 1, "why": "The past form is konnte; könnte expresses a possibility or hypothetical situation."}, {"q": "Sie ___ den ganzen Brief.", "options": ["leste", "lesen", "las"], "answer": 2, "why": "Lesen is strong: lesen – las – gelesen."}, {"q": "Ich ___ gestern sehr müde.", "options": ["war", "waren", "wäre"], "answer": 0, "why": "War is the Präteritum of sein for ich."}, {"q": "Wir ___ den Weg nicht.", "options": ["wusste", "wussten", "wissen"], "answer": 1, "why": "The plural Präteritum is wir wussten."}, {"q": "Er ___ ein Buch aus dem Regal.", "options": ["nahm", "nehmt", "genommen"], "answer": 0, "why": "Nehmen has the strong Präteritum nahm."}, {"q": "Die Kinder ___ bis spät im Garten.", "options": ["spielte", "spielten", "gespielt"], "answer": 1, "why": "Regular Präteritum uses -te plus the plural ending: spielten."}, {"q": "Sie ___ uns eine lange Geschichte (sie = eine Frau).", "options": ["erzählten", "erzählen", "erzählte"], "answer": 2, "why": "The singular regular past form is erzählte."}, {"q": "Der Zug ___ pünktlich ab.", "options": ["fuhr", "fahrt", "gefahren"], "answer": 0, "why": "Abfahren has the strong past form fuhr ... ab."}], "guide": {"steps": ["Identify whether the verb is regular or strong/irregular.", "For regular verbs, form the -te past stem; for strong verbs learn the changed stem.", "Add the subject ending. Ich and er/sie/es share the same ordinary Präteritum form."], "examples": [["ich machte · du machtest · wir machten", "Regular past formation."], ["ich ging · du gingst · wir gingen", "A strong verb changes its stem."]], "trap": "War and wäre are different: war is past fact, wäre is hypothetical."}}, {"title": "Plusquamperfekt & event order", "cat": "Grammar", "group": "Tenses", "rule": "Use hatte or war + past participle for an event completed before another past event. Nachdem often introduces the earlier event. The later event can be expressed in Präteritum or Perfekt.", "example": "Nachdem der Zug abgefahren war, kamen wir am Bahnhof an.", "translation": "After the train had departed, we arrived at the station.", "questions": [{"q": "Nachdem ich gegessen ___, ging ich los.", "options": ["hatte", "habe", "bin"], "answer": 0, "why": "Essen uses haben; the earlier past event takes hatte gegessen."}, {"q": "Sie war schon ___, als ich anrief.", "options": ["gehen", "gegangen", "ging"], "answer": 1, "why": "Plusquamperfekt uses war + the participle gegangen."}, {"q": "Welche Handlung war zuerst? „Er hatte bezahlt, bevor er ging.“", "options": ["Er ging.", "Beide gleichzeitig.", "Er bezahlte."], "answer": 2, "why": "Hatte bezahlt marks the earlier action."}, {"q": "Bevor wir ankamen, ___ die Gäste schon gegangen.", "options": ["hatten", "waren", "sind"], "answer": 1, "why": "Gehen uses sein, so the earlier past action is waren gegangen."}, {"q": "Sie hatte den Schlüssel ___.", "options": ["vergessen", "vergaß", "vergisst"], "answer": 0, "why": "Plusquamperfekt uses hatte + past participle."}, {"q": "Nachdem wir bezahlt hatten, ___ wir nach Hause.", "options": ["gingen", "gegangen", "gehen zu"], "answer": 0, "why": "The later past action is expressed here with gingen."}, {"q": "Ich ___ noch nie in Wien gewesen, bevor ich umzog.", "options": ["hatte", "war", "bin"], "answer": 1, "why": "Sein forms Plusquamperfekt with war gewesen."}, {"q": "Was geschah zuerst? „Als wir ankamen, hatte der Film begonnen.“", "options": ["Wir kamen an.", "Der Film begann.", "Beides gleichzeitig."], "answer": 1, "why": "Hatte begonnen marks the earlier event."}, {"q": "Er war müde, weil er schlecht ___ hatte.", "options": ["schläft", "schlafen", "geschlafen"], "answer": 2, "why": "The earlier action is hatte geschlafen; the finite verb is last in the weil clause."}], "guide": {"steps": ["Find the earlier of two past events.", "Use hatte for a haben verb or war for a sein verb.", "Combine it with the participle. Tell the later past event with an appropriate past tense."], "examples": [["Nachdem ich gekocht hatte, aßen wir.", "Cooking was completed before eating."], ["Der Zug war abgefahren, als wir ankamen.", "Departure was completed before arrival."]], "trap": "Use event order to choose the tense; do not put every past event into Plusquamperfekt."}}, {"title": "Futur I & future arrangements", "cat": "Grammar", "group": "Tenses", "rule": "Futur I uses werden + infinitive. It can express a prediction, intention or assumption. German also often uses the present tense with a future time expression for a fixed arrangement.", "example": "Morgen treffen wir uns um zehn. Es wird bestimmt interessant werden.", "translation": "Tomorrow we are meeting at ten. It will surely be interesting.", "questions": [{"q": "Ich ___ dich morgen anrufen.", "options": ["wirst", "werde", "werden"], "answer": 1, "why": "Ich takes werde; anrufen stays an infinitive."}, {"q": "Wir werden nächstes Jahr nach Wien ___.", "options": ["reisen", "gereist", "reist"], "answer": 0, "why": "Futur I uses the infinitive reisen."}, {"q": "„Morgen beginnt der Kurs.“ bezieht sich auf …", "options": ["die Vergangenheit", "eine Gewohnheit", "die Zukunft"], "answer": 2, "why": "Morgen gives a future time even though beginnt is present tense."}, {"q": "Du ___ bald besser Deutsch sprechen.", "options": ["wird", "wirst", "werde"], "answer": 1, "why": "Du takes wirst in Futur I."}, {"q": "Wir ___ nächste Woche umziehen.", "options": ["werden", "wird", "werdet"], "answer": 0, "why": "Wir takes werden plus infinitive umziehen."}, {"q": "Sie wird morgen früh ___.", "options": ["ankam", "angekommen", "ankommen"], "answer": 2, "why": "Futur I takes the infinitive."}, {"q": "„Nächsten Montag habe ich einen Termin.“ Welche Zeit ist gemeint?", "options": ["Vergangenheit", "Zukunft", "Nur Gegenwart"], "answer": 1, "why": "A future time expression can give present tense future meaning."}, {"q": "Ihr ___ das bestimmt schaffen.", "options": ["werdet", "werden", "wirst"], "answer": 0, "why": "The ihr form of werden is werdet."}, {"q": "„Er wird wohl zu Hause sein.“ drückt hier aus …", "options": ["eine Vermutung", "einen Befehl", "eine vergangene Tatsache"], "answer": 0, "why": "Werden with wohl can express a present assumption."}], "guide": {"steps": ["Decide whether you need a prediction, intention or assumption, or simply a future arrangement.", "For Futur I, conjugate werden and use the infinitive at the end.", "For a fixed future arrangement, the present tense plus a clear time expression is often enough."], "examples": [["Ich werde dich morgen anrufen.", "Werden + infinitive anrufen."], ["Morgen treffen wir uns um zehn.", "Present tense, but morgen makes the future reference clear."]], "trap": "The word werden alone does not always mean future: wird repariert is passive, while wird reparieren is future."}}, {"title": "Modal verbs & necessity", "cat": "Grammar", "group": "Verbs", "rule": "Modal verbs combine with an infinitive at the end: müssen, können, dürfen, sollen, wollen and mögen. Nicht müssen means that something is not necessary; nicht dürfen means that it is forbidden. Möchten is a polite way to express a wish.", "example": "Du musst nicht kommen, aber du darfst gern mitmachen.", "translation": "You do not have to come, but you are welcome to join in.", "questions": [{"q": "Hier darf man nicht rauchen. Das bedeutet …", "options": ["Rauchen ist verboten.", "Rauchen ist nicht nötig.", "Rauchen ist erwünscht."], "answer": 0, "why": "Nicht dürfen expresses a prohibition."}, {"q": "Ich ___ heute länger arbeiten, weil viel zu tun ist.", "options": ["darf nicht", "muss", "möchte nicht"], "answer": 1, "why": "Müssen expresses necessity here."}, {"q": "Du musst nicht bezahlen. Du ___ kostenlos teilnehmen.", "options": ["musst", "sollst nicht", "kannst"], "answer": 2, "why": "Kannst expresses that participation is possible without payment."}, {"q": "Du ___ hier nicht parken. Es ist verboten.", "options": ["musst", "darfst", "willst"], "answer": 1, "why": "Nicht dürfen expresses prohibition."}, {"q": "Wir müssen heute nicht arbeiten. Das bedeutet …", "options": ["Es ist verboten.", "Es ist nicht nötig.", "Es ist unmöglich."], "answer": 1, "why": "Nicht müssen removes necessity; it does not forbid the action."}, {"q": "Ich ___ gern ein Glas Wasser.", "options": ["möchte", "mögen", "möchtet"], "answer": 0, "why": "Möchte expresses a polite wish with ich."}, {"q": "Ihr ___ die Hausaufgaben bis Freitag machen.", "options": ["soll", "sollen", "sollt"], "answer": 2, "why": "Ihr takes sollt; this describes an assigned task."}, {"q": "Sie kann sehr gut ___.", "options": ["schwimmt", "schwimmen", "zu schwimmen"], "answer": 1, "why": "A modal verb combines with an infinitive without zu."}, {"q": "Er ___ früher jeden Tag arbeiten.", "options": ["müsste", "musste", "müssen"], "answer": 1, "why": "Früher calls for the past form musste here."}], "guide": {"steps": ["Choose the meaning: necessity, ability, permission, obligation or desire.", "Conjugate the modal verb for the subject.", "Put the other verb at the end as an infinitive without zu."], "examples": [["Du musst nicht kommen.", "Coming is not necessary."], ["Du darfst nicht kommen.", "Coming is not permitted."]], "trap": "Nicht müssen and nicht dürfen are not interchangeable."}}, {"title": "Reflexive verbs", "cat": "Grammar", "group": "Verbs", "rule": "Reflexive pronouns refer back to the subject. Accusative: mich, dich, sich, uns, euch, sich. Use dative mir or dir when another accusative object is present, for example ich wasche mir die Hände. Some verbs are learned with sich and a fixed preposition.", "example": "Ich erinnere mich an den Termin und ziehe mir eine Jacke an.", "translation": "I remember the appointment and put on a jacket.", "questions": [{"q": "Wir freuen ___ auf den Urlaub.", "options": ["sich", "euch", "uns"], "answer": 2, "why": "Wir takes the reflexive pronoun uns."}, {"q": "Ich wasche ___ die Hände.", "options": ["mich", "mir", "sich"], "answer": 1, "why": "Die Hände is the accusative object, so the reflexive pronoun is dative mir."}, {"q": "Er interessiert ___ für Politik.", "options": ["sich", "ihm", "mich"], "answer": 0, "why": "The combination is sich interessieren für; er takes sich."}, {"q": "Du musst ___ beeilen.", "options": ["dich", "dir", "sich"], "answer": 0, "why": "Sich beeilen uses accusative: du beeilst dich."}, {"q": "Sie freut ___ über das Geschenk.", "options": ["ihr", "sich", "mich"], "answer": 1, "why": "For sie, the reflexive pronoun is sich."}, {"q": "Wir interessieren ___ für Kunst.", "options": ["sich", "euch", "uns"], "answer": 2, "why": "Wir takes uns in sich interessieren."}, {"q": "Ich putze ___ die Zähne.", "options": ["mich", "mir", "sich"], "answer": 1, "why": "Die Zähne is an accusative object, so the reflexive pronoun is dative mir."}, {"q": "Ihr solltet ___ ausruhen.", "options": ["euch", "uns", "sich"], "answer": 0, "why": "The reflexive pronoun for ihr is euch."}, {"q": "Er erinnert ___ an den Termin.", "options": ["ihm", "ihn", "sich"], "answer": 2, "why": "The reflexive combination is sich erinnern an."}], "guide": {"steps": ["Check whether the verb is reflexive and learn it with sich.", "Choose a pronoun matching the subject.", "Use dative mir/dir when another direct accusative object is present."], "examples": [["Ich wasche mich.", "Mich is the direct object."], ["Ich wasche mir die Hände.", "Die Hände is the direct object, so the reflexive pronoun is mir."]], "trap": "Er freut ihm is incorrect for the reflexive meaning; use Er freut sich."}}, {"title": "The imperative", "cat": "Grammar", "group": "Verbs", "rule": "The imperative gives instructions or requests. For du, use the imperative stem; for ihr, use the present-tense ihr form without ihr. The formal form places Sie after the verb. Bitte makes a request friendlier. Sein has the special forms sei, seid and seien Sie.", "example": "Bitte ruf mich morgen an! Seien Sie bitte pünktlich.", "translation": "Please call me tomorrow! Please be on time.", "questions": [{"q": "Formal: ___ Sie bitte Platz!", "options": ["Nimm", "Nehmt", "Nehmen"], "answer": 2, "why": "The formal imperative is Nehmen Sie."}, {"q": "To several friends: ___ bitte leise!", "options": ["Sei", "Seid", "Seien Sie"], "answer": 1, "why": "The ihr imperative of sein is seid."}, {"q": "To one friend: ___ mir bitte!", "options": ["Hilf", "Helft", "Helfen"], "answer": 0, "why": "Helfen has the singular imperative hilf."}, {"q": "Zu einer Freundin: ___ bitte pünktlich!", "options": ["Sei", "Seid", "Seien"], "answer": 0, "why": "The du imperative of sein is sei."}, {"q": "Zu mehreren Freunden: ___ bitte die Fenster!", "options": ["Öffne", "Öffnet", "Öffnen Sie"], "answer": 1, "why": "The ihr imperative uses öffnet without ihr."}, {"q": "Formell: ___ Sie bitte hier!", "options": ["Warte", "Wartet", "Warten"], "answer": 2, "why": "The formal imperative places Sie after the verb: Warten Sie."}, {"q": "Zu einem Freund: ___ das Buch!", "options": ["Lies", "Lese Sie", "Lesen"], "answer": 0, "why": "Lesen has the du imperative lies."}, {"q": "Zu einer Freundin: ___ mich bitte morgen an!", "options": ["Ruft", "Ruf", "Rufen"], "answer": 1, "why": "The du imperative of anrufen is ruf ... an."}, {"q": "Zu mehreren Personen: ___ bitte vorsichtig!", "options": ["Sei", "Seien", "Seid"], "answer": 2, "why": "The ihr imperative of sein is seid."}], "guide": {"steps": ["Choose your listener: one friend (du), several friends (ihr), or formal Sie.", "Use the correct imperative form, including special forms such as sei, seid and seien Sie.", "Separate prefixes as in main clauses and add bitte for a friendlier request."], "examples": [["Ruf mich bitte an!", "Du imperative of anrufen."], ["Rufen Sie mich bitte an!", "Formal imperative includes Sie after the verb."]], "trap": "Do not mix the du form with formal Sie: use Nehmen Sie, not Nimm Sie."}}, {"title": "Nouns, gender & plural", "cat": "Grammar", "group": "Nouns and articles", "rule": "Learn nouns together with their article and plural. Nouns ending in -ung, -heit and -keit are generally feminine; diminutives ending in -chen are neuter. Plurals vary: do not assume that every noun simply adds -s. All nouns begin with a capital letter.", "example": "Die Entscheidung ist wichtig. Die Entscheidungen sind schwierig.", "translation": "The decision is important. The decisions are difficult.", "questions": [{"q": "___ Möglichkeit ist interessant.", "options": ["Der", "Die", "Das"], "answer": 1, "why": "Nouns ending in -keit are feminine."}, {"q": "Das Mädchen ist klein. „Mädchen“ ist grammatisch …", "options": ["maskulin", "feminin", "neutral"], "answer": 2, "why": "The diminutive ending -chen makes the noun neuter."}, {"q": "Plural: das Buch → die ___.", "options": ["Bücher", "Buchen", "Buchs"], "answer": 0, "why": "The plural is Bücher, with an umlaut and -er."}, {"q": "___ Zeitung liegt auf dem Tisch.", "options": ["Der", "Die", "Das"], "answer": 1, "why": "Zeitung is feminine; -ung is a useful feminine ending."}, {"q": "___ Brötchen ist frisch.", "options": ["Das", "Die", "Der"], "answer": 0, "why": "Diminutives ending in -chen are neuter."}, {"q": "Plural: der Apfel → die ___.", "options": ["Apfeln", "Äpfel", "Apfels"], "answer": 1, "why": "The plural is Äpfel."}, {"q": "Plural: die Wohnung → die ___.", "options": ["Wohnungen", "Wohnungs", "Wohnunge"], "answer": 0, "why": "Nouns ending in -ung generally form their plural with -en."}, {"q": "Welche Schreibweise ist richtig?", "options": ["das auto", "das Auto", "Das auto"], "answer": 1, "why": "German nouns are capitalised."}, {"q": "___ Gesundheit ist wichtig.", "options": ["Der", "Das", "Die"], "answer": 2, "why": "Gesundheit is feminine; -heit is a feminine ending."}], "guide": {"steps": ["Learn every new noun with its article and plural.", "Use endings such as -ung/-heit/-keit and -chen as helpful gender clues.", "Capitalise nouns and learn irregular plurals as complete words."], "examples": [["die Zeitung → die Zeitungen", "-ung nouns are feminine and normally add -en in the plural."], ["das Buch → die Bücher", "An irregular plural with an umlaut."]], "trap": "A noun’s grammatical gender is not always the natural gender of a person: das Mädchen is neuter."}}, {"title": "Articles & the four cases", "cat": "Grammar", "group": "Nouns and articles", "rule": "The subject is nominative. A direct object is often accusative; an indirect recipient is often dative. Verbs and prepositions can also require specific cases. Definite articles: der/den/dem/des for masculine; die/die/der/der for feminine; das/das/dem/des for neuter; die/die/den/der for plural.", "example": "Die Frau gibt dem Kind einen Apfel.", "translation": "The woman gives the child an apple.", "questions": [{"q": "Ich sehe ___ Mann.", "options": ["der", "dem", "den"], "answer": 2, "why": "The direct object is masculine accusative: den Mann."}, {"q": "Sie hilft ___ Nachbarin.", "options": ["die", "der", "das"], "answer": 1, "why": "Helfen requires dative: der Nachbarin."}, {"q": "___ Kind spielt im Garten.", "options": ["Das", "Dem", "Den"], "answer": 0, "why": "The subject is nominative: das Kind."}, {"q": "___ Lehrer erklärt die Aufgabe.", "options": ["Der", "Den", "Dem"], "answer": 0, "why": "The person performing the action is the nominative subject."}, {"q": "Ich gebe ___ Frau das Buch.", "options": ["die", "der", "den"], "answer": 1, "why": "The recipient is dative; feminine dative uses der."}, {"q": "Das ist die Tasche ___ Kindes.", "options": ["des", "dem", "das"], "answer": 0, "why": "Possession is expressed with genitive des Kindes."}, {"q": "Wir sehen ___ Hund.", "options": ["der", "dem", "den"], "answer": 2, "why": "A masculine direct object takes accusative den."}, {"q": "Mit ___ Freunden gehe ich ins Kino.", "options": ["die", "den", "der"], "answer": 1, "why": "Mit requires dative; plural uses den Freunden."}, {"q": "___ Kind bekommt einen Apfel.", "options": ["Das", "Dem", "Den"], "answer": 0, "why": "The recipient of bekommt is still the grammatical subject, so use nominative das."}], "guide": {"steps": ["Find the subject: normally nominative.", "Find direct objects and recipients, but also check verbs/prepositions with a required case.", "Choose the article for that case, gender and number."], "examples": [["Der Mann sieht den Hund.", "The subject is nominative; the direct object is accusative."], ["Die Frau gibt dem Kind einen Apfel.", "Recipient: dative dem Kind. Direct object: accusative einen Apfel."]], "trap": "Meaning alone is not enough: helfen requires dative, and the subject of bekommen remains nominative."}}, {"title": "Genitive & n-declension", "cat": "Grammar", "group": "Nouns and articles", "rule": "The genitive expresses possession. Masculine and neuter nouns often add -(e)s: des Mannes, des Kindes. A group of masculine nouns, such as der Student and der Kollege, take -(e)n in every singular case except nominative. Learn these as n-declension nouns.", "example": "Das Fahrrad des Studenten steht vor der Tür.", "translation": "The student’s bicycle is by the door.", "questions": [{"q": "Ich spreche mit dem ___.", "options": ["Student", "Studenten", "Students"], "answer": 1, "why": "Student is an n-declension noun: dem Studenten."}, {"q": "Das ist das Auto meines ___.", "options": ["Vaters", "Vater", "Vätern"], "answer": 0, "why": "Masculine genitive singular: meines Vaters."}, {"q": "Ich kenne den ___ gut.", "options": ["Kollege", "Kolleges", "Kollegen"], "answer": 2, "why": "Kollege takes -n in accusative singular: den Kollegen."}, {"q": "Wir sprechen mit dem ___.", "options": ["Kollege", "Kollegen", "Kolleges"], "answer": 1, "why": "Kollege is an n-declension noun: dem Kollegen."}, {"q": "Das Haus des ___ ist groß.", "options": ["Nachbarn", "Nachbar", "Nachbarsn"], "answer": 0, "why": "Nachbar follows n-declension here: des Nachbarn."}, {"q": "Ich sehe den ___ im Garten.", "options": ["Junge", "Junges", "Jungen"], "answer": 2, "why": "Junge adds -n in accusative singular."}, {"q": "Das Spielzeug des ___ ist neu.", "options": ["Kind", "Kindes", "Kindern"], "answer": 1, "why": "Neuter Kind takes genitive -(e)s: des Kindes."}, {"q": "Der Name meines ___ ist Paul.", "options": ["Bruders", "Bruder", "Brüdern"], "answer": 0, "why": "Bruder forms the singular genitive with -s."}, {"q": "Ich helfe einem ___.", "options": ["Student", "Studenten", "Students"], "answer": 1, "why": "Student is an n-declension noun; dative singular is Studenten."}], "guide": {"steps": ["For possession, choose the genitive article and noun form.", "Masculine/neuter genitive nouns often add -(e)s.", "For n-declension masculine nouns, add -(e)n in all singular cases except nominative."], "examples": [["das Auto des Lehrers", "Ordinary masculine genitive with -s."], ["der Student → mit dem Studenten", "N-declension: -en after the dative article."]], "trap": "Do not apply -s to every masculine noun: des Studenten, not des Students."}}, {"title": "Personal & possessive pronouns", "cat": "Grammar", "group": "Pronouns", "rule": "Personal pronouns change with case: ich/mich/mir, du/dich/dir, er/ihn/ihm. Possessives such as mein and dein take endings based on the possessed noun, not the owner. Learn pronouns in short sentences to connect the form with its role.", "example": "Ich gebe ihr mein Buch. Sie gibt mir ihren Stift.", "translation": "I give her my book. She gives me her pen.", "questions": [{"q": "Der Mann ist nett. Ich helfe ___.", "options": ["ihn", "ihm", "er"], "answer": 1, "why": "Helfen requires dative: ihm."}, {"q": "Das ist Anna. Kennst du ___?", "options": ["ihr", "sie", "ihnen"], "answer": 1, "why": "Kennen takes accusative: sie."}, {"q": "Ich besuche ___ Schwester.", "options": ["meinen", "meinem", "meine"], "answer": 2, "why": "Schwester is feminine accusative: meine Schwester."}, {"q": "Das Fahrrad gehört ___ (ich).", "options": ["mich", "mir", "ich", "mein"], "answer": 1, "why": "Gehören takes dative; ich becomes mir."}, {"q": "Ich spreche mit ___ (sie, singular).", "options": ["ihm", "sie", "ihr", "ihnen"], "answer": 2, "why": "After mit, feminine singular sie becomes ihr."}, {"q": "Der Kurs gefällt ___ (wir).", "options": ["wir", "unser", "euch", "uns"], "answer": 3, "why": "Gefallen takes a dative experiencer: uns."}, {"q": "Ich fahre mit ___ (ihr).", "options": ["euer", "euch", "ihnen", "ihr"], "answer": 1, "why": "Plural familiar ihr becomes euch after mit."}, {"q": "Kann ich ___ helfen? (formal Sie)", "options": ["Ihren", "Sie", "Ihnen", "Ihr"], "answer": 2, "why": "Formal dative Ihnen is capitalised."}, {"q": "Die Ärztin erklärt ___ den Befund (wir).", "options": ["uns", "wir", "unser", "euch"], "answer": 0, "why": "The people receiving the explanation are dative: uns."}], "guide": {"steps": ["For personal pronouns, identify the case required by the verb or preposition.", "For possessives, identify who owns it, then the case/gender/number of the thing owned.", "Choose the ending according to that owned noun."], "examples": [["Ich sehe ihn. / Ich helfe ihm.", "Accusative after sehen, dative after helfen."], ["mein Bruder → mit meinem Bruder", "The owner remains ich; the ending changes because Bruder is dative."]], "trap": "The owner’s gender does not determine the adjective-like ending of mein/dein/ihr."}}, {"title": "Comparatives & superlatives", "cat": "Grammar", "group": "Adjectives", "rule": "Use -er for a comparison and als for two unequal things. Equal things use so ... wie. Many adjectives form a superlative with am ... -sten. Irregular forms include gut – besser – am besten and viel – mehr – am meisten.", "example": "Der Zug ist schneller als der Bus, aber das Fahrrad ist am billigsten.", "translation": "The train is faster than the bus, but the bicycle is the cheapest.", "questions": [{"q": "Heute geht es mir ___ als gestern.", "options": ["gut", "besser", "am besten"], "answer": 1, "why": "The comparative of gut is besser."}, {"q": "Mein Zimmer ist so groß ___ deins.", "options": ["als", "wie", "denn"], "answer": 1, "why": "Equal comparisons use so ... wie."}, {"q": "Von allen läuft Lea am ___.", "options": ["schneller", "schnell", "schnellsten"], "answer": 2, "why": "The superlative is am schnellsten."}, {"q": "Dieses Buch ist ___ als das andere.", "options": ["interessant", "interessanter", "am interessantesten"], "answer": 1, "why": "Als compares two unequal things using the comparative."}, {"q": "Er ist genauso alt ___ ich.", "options": ["als", "wie", "denn"], "answer": 1, "why": "Equal comparisons use genauso ... wie."}, {"q": "Von allen Städten gefällt mir Bern am ___.", "options": ["besten", "besser", "gut"], "answer": 0, "why": "The superlative of gut is am besten."}, {"q": "Ich trinke heute ___ Kaffee als sonst.", "options": ["viel", "am meisten", "mehr"], "answer": 2, "why": "The comparative of viel is mehr."}, {"q": "Mein Bruder ist ___ als ich.", "options": ["jünger", "jung", "am jüngsten"], "answer": 0, "why": "Jung takes an umlaut in the comparative: jünger."}, {"q": "Der Weg ist nicht so lang ___ gestern.", "options": ["als", "wie", "dass"], "answer": 1, "why": "So ... wie expresses an equal comparison, including its negated form."}], "guide": {"steps": ["For unequal things, use the comparative and als.", "For equal things, use so/genauso ... wie.", "For the highest degree, use a superlative and learn common irregular forms."], "examples": [["Berlin ist größer als Bonn.", "Unequal comparison with comparative + als."], ["gut → besser → am besten", "An irregular comparison pattern."]], "trap": "Do not use wie after an ordinary unequal comparative: größer als, not größer wie in standard written German."}}, {"title": "Adverbs: time, place & manner", "cat": "Grammar", "group": "Adverbs", "rule": "Adverbs describe circumstances and generally do not take adjective endings. Time information often comes before manner and place when all are neutral new information, but emphasis can change the order. Erst means not before a point in time or only so far; schon suggests earlier than expected or already.", "example": "Wir fahren morgen mit dem Zug nach Hamburg.", "translation": "We are travelling to Hamburg by train tomorrow.", "questions": [{"q": "Sie kommt nicht heute, sondern ___ morgen.", "options": ["erst", "schon", "immer"], "answer": 0, "why": "Erst morgen means not until tomorrow."}, {"q": "„Dort“ beantwortet welche Frage?", "options": ["Wann?", "Wo?", "Warum?"], "answer": 1, "why": "Dort is a place adverb: where?"}, {"q": "Er spricht ___.", "options": ["langsamen", "langsamerem", "langsam"], "answer": 2, "why": "An adverb modifying spricht does not take an adjective ending."}, {"q": "„Gestern“ beantwortet die Frage …", "options": ["Wo?", "Wann?", "Wie?"], "answer": 1, "why": "Gestern is a time adverb."}, {"q": "„Hier“ beantwortet die Frage …", "options": ["Wo?", "Wann?", "Warum?"], "answer": 0, "why": "Hier describes a location."}, {"q": "Sie erklärt die Aufgabe ___.", "options": ["deutlichen", "deutlicherem", "deutlich"], "answer": 2, "why": "An adverb modifying a verb does not take adjective endings."}, {"q": "Es ist erst sieben. „Erst“ bedeutet hier …", "options": ["später als erwartet", "früher bzw. weniger weit fortgeschritten als erwartet", "immer"], "answer": 1, "why": "Erst sieben suggests it is only seven, earlier than expected."}, {"q": "Ich habe die Aufgabe ___ fertig. Ich brauche keine Zeit mehr.", "options": ["schon", "erst morgen", "nie"], "answer": 0, "why": "Schon means already."}, {"q": "Wir fahren morgen mit dem Bus nach Hause. Was ist die Zeitangabe?", "options": ["mit dem Bus", "nach Hause", "morgen"], "answer": 2, "why": "Morgen gives the time; mit dem Bus is the means and nach Hause the destination."}], "guide": {"steps": ["Ask what the word describes: when, where, how or why.", "If it modifies a verb as an adverb, do not add an adjective ending.", "Use context to distinguish time expectations such as schon and erst."], "examples": [["Sie spricht langsam.", "Langsam describes how she speaks; no adjective ending."], ["Es ist erst sieben. / Es ist schon sieben.", "Only seven versus already seven: different expectations."]], "trap": "A useful default order is not an absolute rule; information focus can change German word order."}}, {"title": "Dative & accusative prepositions", "cat": "Grammar", "group": "Prepositions", "rule": "Always-dative prepositions include aus, bei, mit, nach, seit, von and zu. Always-accusative prepositions include durch, für, gegen, ohne and um. Contract common pairs: zu dem → zum, zu der → zur, bei dem → beim. Seit usually describes a situation continuing into the present.", "example": "Seit einem Jahr fahre ich mit dem Bus zur Arbeit.", "translation": "For a year now, I have been taking the bus to work.", "questions": [{"q": "Das Geschenk ist für ___ Bruder.", "options": ["meinem", "meinen", "meiner"], "answer": 1, "why": "Für requires accusative: meinen Bruder."}, {"q": "Ich wohne seit ___ Monat hier.", "options": ["einem", "einen", "einer"], "answer": 0, "why": "Seit requires dative: einem Monat."}, {"q": "Ohne ___ geht es nicht.", "options": ["dir", "du", "dich"], "answer": 2, "why": "Ohne requires accusative: dich."}, {"q": "Ich komme mit ___ Zug.", "options": ["der", "dem", "den", "das"], "answer": 1, "why": "Zug is masculine; mit requires dative."}, {"q": "Wir helfen ___ Kindern.", "options": ["der", "dem", "die", "den"], "answer": 3, "why": "Dative plural uses den; Kindern already has the dative -n."}, {"q": "Nach ___ Konzert gehen wir nach Hause.", "options": ["der", "das", "den", "dem"], "answer": 3, "why": "Konzert is neuter; nach requires dative."}, {"q": "Er spricht mit ___ Kollegin.", "options": ["einen", "einem", "ein", "einer"], "answer": 3, "why": "Kollegin is feminine dative: mit einer Kollegin."}, {"q": "Sie kommt aus ___ Schweiz.", "options": ["die", "den", "dem", "der"], "answer": 3, "why": "Schweiz is feminine with an article; aus takes dative."}, {"q": "Wir erhalten Hilfe von ___ Nachbarin.", "options": ["unserem", "unserer", "unsere", "unseren"], "answer": 1, "why": "Nachbarin is feminine dative after von."}], "guide": {"steps": ["Check whether the preposition always takes dative or accusative.", "Dative examples: mit, nach, bei, seit, von, zu, aus. Accusative examples: durch, für, gegen, ohne, um.", "Choose the noun/pronoun form after the preposition; learn common contractions."], "examples": [["für den Mann / mit dem Mann", "The same noun changes case because the preposition changes."], ["zu dem Arzt → zum Arzt; zu der Ärztin → zur Ärztin", "Common contractions keep the dative meaning."]], "trap": "Do not use the two-way-preposition destination rule with zu: zu always requires dative."}}, {"title": "Questions & indirect questions", "cat": "Grammar", "group": "Sentence structure", "rule": "Yes/no questions start with the finite verb. W-questions start with the question word, followed by the finite verb. Indirect questions have verb-final order; use ob for an indirect yes/no question. Do not use wenn to mean whether.", "example": "Können Sie mir sagen, wann der Zug abfährt?", "translation": "Can you tell me when the train departs?", "questions": [{"q": "Weißt du, ___ er heute kommt?", "options": ["wenn", "ob", "als"], "answer": 1, "why": "Ob introduces an indirect yes/no question."}, {"q": "Wo ___ du?", "options": ["wohnst", "du wohnst", "wohnen"], "answer": 0, "why": "The question word is followed by the finite verb: Wo wohnst du?"}, {"q": "Können Sie sagen, wo der Bahnhof ___?", "options": ["sein", "sind", "ist"], "answer": 2, "why": "The finite verb comes at the end of the indirect question."}, {"q": "___ Sie morgen Zeit?", "options": ["Haben", "Sie haben", "Hat"], "answer": 0, "why": "A yes/no question begins with the finite verb."}, {"q": "Weißt du, wo er ___?", "options": ["wohnt", "wohnen", "er wohnt"], "answer": 0, "why": "The indirect question has its finite verb at the end."}, {"q": "Ich frage mich, ___ sie noch arbeitet.", "options": ["wenn", "ob", "als"], "answer": 1, "why": "Ob introduces an indirect yes/no question."}, {"q": "___ fährt der nächste Zug? – Um neun.", "options": ["Wo", "Warum", "Wann"], "answer": 2, "why": "A time answer calls for wann."}, {"q": "Können Sie mir sagen, wie viel das Ticket ___?", "options": ["kostet", "kosten", "es kostet"], "answer": 0, "why": "The conjugated verb ends the indirect question."}, {"q": "Warum ___ du Deutsch?", "options": ["du lernst", "lernst", "lernen"], "answer": 1, "why": "In a direct W-question, the finite verb follows the question word."}], "guide": {"steps": ["For yes/no questions, begin with the conjugated verb.", "For direct W-questions, place the question word first and the finite verb next.", "For indirect questions, use ob or the W-word and put the finite verb at the end."], "examples": [["Kommt er? → Weißt du, ob er kommt?", "Yes/no question becomes an ob clause."], ["Wann kommt er? → Weißt du, wann er kommt?", "The question word stays, but verb position changes."]], "trap": "Use ob for whether; wenn normally means if/when, not an indirect yes/no question."}}, {"title": "Negation: nicht & kein", "cat": "Grammar", "group": "Sentence structure", "rule": "Kein negates a noun with an indefinite article or no article: ein Auto → kein Auto. Nicht negates verbs, adjectives, definite noun phrases or particular sentence parts. Its position depends on what is negated. Learn examples rather than treating nicht as always the last word.", "example": "Ich habe kein Auto. Heute fahre ich nicht mit dem Bus.", "translation": "I do not have a car. Today I am not taking the bus.", "questions": [{"q": "Ich habe ___ Zeit.", "options": ["nicht", "keine", "keinen"], "answer": 1, "why": "Zeit is a feminine noun without an article: keine Zeit."}, {"q": "Das ist ___ mein Schlüssel.", "options": ["kein", "keine", "nicht"], "answer": 2, "why": "A possessive phrase is negated with nicht."}, {"q": "Der Film ist ___ interessant.", "options": ["nicht", "kein", "keine"], "answer": 0, "why": "Use nicht to negate the adjective interessant."}, {"q": "Ich trinke ___ Kaffee.", "options": ["nicht", "keinen", "keinem"], "answer": 1, "why": "Kaffee is an indefinite masculine accusative noun phrase: keinen Kaffee."}, {"q": "Das ist ___ meine Tasche.", "options": ["kein", "keine", "nicht"], "answer": 2, "why": "Negate a possessive phrase with nicht."}, {"q": "Der Film war ___ langweilig.", "options": ["nicht", "kein", "keinen"], "answer": 0, "why": "An adjective is negated with nicht."}, {"q": "Wir haben ___ Auto.", "options": ["keinen", "kein", "keinem"], "answer": 1, "why": "Auto is neuter accusative: kein Auto."}, {"q": "Sie kommt heute ___.", "options": ["nicht", "keine", "kein"], "answer": 0, "why": "Use nicht to negate the action or sentence."}, {"q": "Hier gibt es ___ freien Plätze.", "options": ["keinen", "keinem", "keine"], "answer": 2, "why": "The plural accusative noun phrase takes keine freien Plätze."}], "guide": {"steps": ["Negate an indefinite/no-article noun phrase with kein.", "Use nicht for adjectives, actions and phrases with definite articles or possessives.", "Place nicht near the part you want to negate, following the sentence structure."], "examples": [["Ich habe ein Auto. → Ich habe kein Auto.", "Kein replaces the indefinite article."], ["Das ist nicht mein Auto.", "A possessive phrase is negated with nicht."]], "trap": "Kein also takes case endings: keinen Kaffee, but kein Wasser."}}, {"title": "Time clauses: als, wenn & bevor", "cat": "Grammar", "group": "Sentence structure", "rule": "Use als for a single event or period in the past. Use wenn for repeated events or conditions, and for future when. Bevor means before and nachdem means after. These conjunctions introduce subordinate clauses with the finite verb at the end.", "example": "Als ich klein war, besuchte ich oft meine Großeltern.", "translation": "When I was little, I often visited my grandparents.", "questions": [{"q": "___ ich gestern ankam, war niemand da.", "options": ["Wenn", "Als", "Ob"], "answer": 1, "why": "A single arrival in the past uses als."}, {"q": "Immer ___ es regnet, nehme ich den Bus.", "options": ["als", "ob", "wenn"], "answer": 2, "why": "A repeated situation uses wenn."}, {"q": "Ich putze die Zähne, ___ ich ins Bett gehe.", "options": ["bevor", "nachdem", "obwohl"], "answer": 0, "why": "The toothbrushing happens before going to bed: bevor."}, {"q": "___ ich ein Kind war, wohnte ich in Köln.", "options": ["Als", "Wenn", "Ob"], "answer": 0, "why": "A single period in the past uses als."}, {"q": "___ ich krank bin, bleibe ich immer zu Hause.", "options": ["Als", "Wenn", "Dass"], "answer": 1, "why": "A repeated situation uses wenn."}, {"q": "Ich rufe dich an, ___ ich angekommen bin.", "options": ["bevor", "nachdem", "ob"], "answer": 1, "why": "The call follows arrival, so use nachdem."}, {"q": "___ du gehst, schließ bitte das Fenster.", "options": ["Bevor", "Nachdem", "Obwohl"], "answer": 0, "why": "The window should be closed before departure."}, {"q": "Morgen, ___ der Kurs beginnt, stelle ich mich vor.", "options": ["als", "wenn", "ob"], "answer": 1, "why": "A future event is introduced with wenn, not als."}, {"q": "Nachdem sie gegessen hatte, ___ sie spazieren.", "options": ["ging", "gegangen", "gehen"], "answer": 0, "why": "The earlier event is Plusquamperfekt; the later past action is ging."}], "guide": {"steps": ["Decide whether the situation is a single past event/period, a repeated event or a future event.", "Use als for a single past event/period and wenn for repeated or future situations.", "Use bevor/nachdem for event order and put the finite verb at the end."], "examples": [["Als ich klein war, wohnte ich in Bonn.", "A single period in the past."], ["Wenn ich Zeit habe, lese ich.", "A repeated condition, not one specific past event."]], "trap": "English when can correspond to als, wenn or wann; choose by meaning, not word-for-word translation."}}, {"title": "Dates, times & appointments", "cat": "Vocabulary practice", "group": "Everyday language", "rule": "Use am with dates and days, um with clock times and im with months or seasons. Dates are ordinal numbers: am dritten Mai. In everyday German halb drei means 2:30, half an hour before three. Use clear clock times when arranging an appointment.", "example": "Der Termin ist am dritten Mai um halb drei.", "translation": "The appointment is on 3 May at half past two.", "questions": [{"q": "„Halb acht“ bedeutet …", "options": ["8:30", "7:30", "8:00"], "answer": 1, "why": "Halb acht is half an hour before eight: 7:30."}, {"q": "Wir treffen uns ___ Montag.", "options": ["am", "im", "um"], "answer": 0, "why": "Days use am: am Montag."}, {"q": "Der Kurs beginnt ___ neun Uhr.", "options": ["am", "im", "um"], "answer": 2, "why": "Clock times use um."}]}, {"title": "Confusing words: kennen, wissen & können", "cat": "Vocabulary practice", "group": "Everyday language", "rule": "Kennen means being familiar with a person, place or thing. Wissen means knowing a fact or answer. Können expresses ability or possibility. Bekommen means to receive, not to become; werden means to become.", "example": "Ich kenne die Stadt, aber ich weiß nicht, wo das Museum ist.", "translation": "I know the city, but I do not know where the museum is.", "questions": [{"q": "___ du die Antwort?", "options": ["Kennst", "Weißt", "Kannst"], "answer": 1, "why": "An answer is a fact: Weißt du die Antwort?"}, {"q": "Ich ___ meine Nachbarn gut.", "options": ["kenne", "weiß", "kann"], "answer": 0, "why": "Familiarity with people uses kennen."}, {"q": "Sie möchte Ärztin ___.", "options": ["bekommen", "wissen", "werden"], "answer": 2, "why": "To become is werden, not bekommen."}]}, {"title": "Useful everyday expressions", "cat": "Vocabulary practice", "group": "Everyday language", "rule": "Learn fixed expressions as complete units. Bescheid sagen means to let someone know. Die Daumen drücken means to wish someone luck. Es kommt darauf an means it depends. These are useful everyday phrases, not word-for-word translations.", "example": "Sag mir bitte Bescheid, wenn du angekommen bist.", "translation": "Please let me know when you have arrived.", "questions": [{"q": "„Ich drücke dir die Daumen!“ bedeutet …", "options": ["Ich wünsche dir Glück.", "Ich bin böse.", "Ich habe keine Zeit."], "answer": 0, "why": "Daumen drücken means to wish someone luck."}, {"q": "„Es kommt darauf an.“ bedeutet …", "options": ["It is arriving.", "It depends.", "It is finished."], "answer": 1, "why": "This fixed expression means it depends."}, {"q": "Bitte sag mir ___.", "options": ["Entscheid", "Unterschied", "Bescheid"], "answer": 2, "why": "Bescheid sagen means to let someone know."}]}, {"title": "Commas & capital letters", "cat": "Writing school", "group": "Writing school", "rule": "German nouns start with capitals. Separate main and subordinate clauses with commas, including relative clauses. A comma is required with infinitive groups introduced by um, ohne or statt. A formal email greeting is followed by a comma; the following word normally starts lowercase unless it is a noun or formal Sie.", "example": "Sehr geehrte Frau Meier,\nvielen Dank für Ihre Nachricht. Ich schreibe Ihnen, weil ich eine Frage habe.", "translation": "Dear Ms Meier, Thank you for your message. I am writing because I have a question.", "questions": [{"q": "Welche Schreibweise ist richtig?", "options": ["Ich lerne deutsch.", "Ich lerne Deutsch.", "ich lerne Deutsch."], "answer": 1, "why": "Deutsch names the language here and is written with a capital letter."}, {"q": "Wo steht das Komma?", "options": ["Ich bleibe, weil ich krank bin.", "Ich, bleibe weil ich krank bin.", "Ich bleibe weil, ich krank bin."], "answer": 0, "why": "The comma separates the main clause from the weil clause."}, {"q": "Welche Anrede ist formell?", "options": ["Hallo Leute!", "Na, du?", "Sehr geehrte Damen und Herren,"], "answer": 2, "why": "Sehr geehrte Damen und Herren is a formal greeting."}]}, {"title": "A polite email: structure & tone", "cat": "Writing school", "group": "Writing school", "rule": "Organise a practical email into a greeting, reason for writing, clear request and closing. Give enough detail for the reader to act. Use Sie/Ihnen/Ihr with capitals in formal correspondence. Polite requests often use könnten or wäre es möglich.", "example": "Könnten Sie mir bitte mitteilen, wann der nächste Kurs beginnt? Vielen Dank im Voraus.", "translation": "Could you please let me know when the next course starts? Thank you in advance.", "questions": [{"q": "Welche Bitte ist höflich und formell?", "options": ["Schick das sofort!", "Könnten Sie mir die Unterlagen schicken?", "Du musst das schicken."], "answer": 1, "why": "Könnten Sie makes a formal request polite."}, {"q": "Welche Schlussformel passt zu einer formellen E-Mail?", "options": ["Mit freundlichen Grüßen", "Bis dann, Kumpel", "Na los!"], "answer": 0, "why": "Mit freundlichen Grüßen is a standard formal closing."}, {"q": "Welche Schreibung ist bei formeller Anrede richtig?", "options": ["ich danke dir", "Ich danke ihnen", "Ich danke Ihnen"], "answer": 2, "why": "Formal Ihnen takes a capital letter."}]}, {"title": "A repair in the flat", "cat": "Reading", "group": "Housing", "rule": "Read the message and identify the problem, the proposed solution and the availability. Notice how a polite request gives specific details.", "example": "Sehr geehrter Herr Weber, seit gestern funktioniert die Heizung in meiner Wohnung nicht mehr. Im Schlafzimmer sind es nur sechzehn Grad. Ich habe versucht, Sie telefonisch zu erreichen, aber leider ohne Erfolg. Könnten Sie bitte einen Handwerker beauftragen? Am Mittwoch arbeite ich zu Hause und bin zwischen acht und zwölf Uhr erreichbar. Falls dieser Zeitraum nicht passt, kann meine Nachbarin am Donnerstag die Tür öffnen. Bitte teilen Sie mir mit, welcher Termin möglich ist. Mit freundlichen Grüßen, Nora Klein", "translation": "Nora’s heating has stopped working. She requests a repair and is available Wednesday morning. Her neighbour can open the door on Thursday if necessary.", "questions": [{"q": "Seit wann funktioniert die Heizung nicht?", "options": ["Seit gestern", "Seit Mittwoch", "Seit einem Monat"], "answer": 0, "why": "The opening says seit gestern."}, {"q": "Wann ist Nora zu Hause erreichbar?", "options": ["Mittwoch zwischen 8 und 12", "Donnerstagabend", "Jeden Tag nach 18 Uhr"], "answer": 0, "why": "She is working from home on Wednesday between eight and twelve."}, {"q": "Was kann die Nachbarin tun?", "options": ["Die Heizung bezahlen", "Am Donnerstag die Tür öffnen", "Nora anrufen"], "answer": 1, "why": "The neighbour can open the door on Thursday."}]}, {"title": "A new working week", "cat": "Reading", "group": "Work", "rule": "Read the announcement and distinguish fixed rules from optional activities. Pay attention to words such as müssen, dürfen and können.", "example": "Ab nächstem Monat dürfen die Mitarbeitenden unserer Firma an zwei Tagen pro Woche zu Hause arbeiten. Für die Planung muss jeder seine gewünschten Tage bis Freitag in den gemeinsamen Kalender eintragen. Dienstags findet weiterhin die Teamsitzung im Büro statt. Neue Mitarbeitende sollen im ersten Monat jeden Tag ins Büro kommen, damit sie das Team kennenlernen. Wer zu Hause keinen geeigneten Arbeitsplatz hat, kann weiterhin die ganze Woche im Büro arbeiten. Am Donnerstag bietet die Firma einen freiwilligen Kurs zum sicheren Umgang mit digitalen Daten an.", "translation": "The company allows two home-office days a week. Staff register days by Friday. Tuesday meetings remain in person, newcomers attend daily in their first month, and a Thursday data-security course is optional.", "questions": [{"q": "Wann findet die Teamsitzung statt?", "options": ["Montags", "Dienstags", "Freitags"], "answer": 1, "why": "The announcement specifies dienstags."}, {"q": "Wer soll zunächst täglich ins Büro kommen?", "options": ["Neue Mitarbeitende", "Alle Mitarbeitenden", "Nur die Kursleitung"], "answer": 0, "why": "New employees should attend daily in their first month."}, {"q": "Ist der Kurs am Donnerstag verpflichtend?", "options": ["Ja, für alle.", "Ja, für neue Mitarbeitende.", "Nein, er ist freiwillig."], "answer": 2, "why": "Freiwillig means voluntary."}]}, {"title": "A neighbourhood garden", "cat": "Reading", "group": "Community", "rule": "Read for opinions and cause-and-effect relationships. Find the sentence that supports each answer.", "example": "Auf einem leeren Grundstück in unserem Viertel entsteht ein Gemeinschaftsgarten. Früher lag dort oft Müll. Jetzt bauen die Nachbarn Gemüse an und teilen die Arbeit. Jeden Samstag treffen sie sich um zehn Uhr. Man braucht keine Erfahrung, denn erfahrene Mitglieder erklären die wichtigsten Aufgaben. Die Teilnahme ist kostenlos, aber alle sollen regelmäßig helfen. Einige Nachbarn hatten zuerst Angst vor Lärm. Deshalb hat die Gruppe vereinbart, nach zwanzig Uhr keine lauten Geräte zu benutzen. Im Herbst ist ein gemeinsames Essen mit dem geernteten Gemüse geplant.", "translation": "Neighbours are turning an empty plot into a shared garden. Beginners are welcome and participation is free, with regular help expected. To address concerns, noisy equipment is not used after 8 pm. A harvest meal is planned.", "questions": [{"q": "Braucht man Erfahrung?", "options": ["Ja, mindestens ein Jahr.", "Nein, andere Mitglieder erklären die Aufgaben.", "Nur beim Essen."], "answer": 1, "why": "Experienced members explain the tasks."}, {"q": "Warum gibt es eine Regel für laute Geräte?", "options": ["Wegen der Sorgen einiger Nachbarn", "Weil Gemüse nachts wächst", "Weil es keine Geräte gibt"], "answer": 0, "why": "Some neighbours feared noise, so the group agreed on a limit."}, {"q": "Was ist für den Herbst geplant?", "options": ["Ein Umzug", "Eine Prüfung", "Ein gemeinsames Essen"], "answer": 2, "why": "The last sentence announces a meal with the harvested vegetables."}]}, {"title": "A train announcement", "cat": "Listening", "group": "Travel", "rule": "Listen for the destination, platform change and delay. You can replay the message before answering.", "example": "Achtung, eine Durchsage für Reisende nach Hamburg. Der Regionalzug um zwölf Uhr zwanzig fährt heute nicht von Gleis vier, sondern von Gleis sieben ab. Wegen Bauarbeiten verzögert sich die Abfahrt um etwa fünfzehn Minuten. Reisende nach Lüneburg können auch den Zug um zwölf Uhr dreißig von Gleis zwei nehmen. Wir bitten um Entschuldigung und wünschen Ihnen eine gute Reise.", "translation": "The Hamburg regional train changes from platform four to seven and is delayed around fifteen minutes. Passengers for Lüneburg have an alternative at 12:30 from platform two.", "questions": [{"q": "Von welchem Gleis fährt der Zug nach Hamburg heute ab?", "options": ["Gleis 4", "Gleis 7", "Gleis 2"], "answer": 1, "why": "The announcement says nicht ... Gleis vier, sondern ... Gleis sieben."}, {"q": "Warum gibt es eine Verspätung?", "options": ["Wegen Bauarbeiten", "Wegen Schnee", "Wegen eines Streiks"], "answer": 0, "why": "Bauarbeiten means construction work."}, {"q": "Wann fährt der alternative Zug nach Lüneburg?", "options": ["12:15", "12:20", "12:30"], "answer": 2, "why": "The alternative leaves at zwölf Uhr dreißig."}]}, {"title": "A course enquiry", "cat": "Listening", "group": "Education", "rule": "Listen for what is included in the price and what must be done before registration. The transcript is available after listening.", "example": "Guten Tag, hier spricht Frau Hoffmann von der Sprachschule. Sie hatten nach unserem Abendkurs gefragt. Der Kurs beginnt am zweiten September und findet montags und mittwochs von achtzehn bis zwanzig Uhr statt. Er kostet zweihundertvierzig Euro. Das Lehrbuch ist nicht im Preis enthalten. Bevor Sie sich anmelden, machen Sie bitte unseren kostenlosen Einstufungstest. Sie können den Test am Freitag zwischen neun und sechzehn Uhr bei uns machen. Eine Anmeldung für den Test ist nicht nötig.", "translation": "The evening course starts 2 September and runs Monday and Wednesday, 6–8 pm. It costs €240 excluding the book. A free placement test is available Friday from 9–4 without an appointment.", "questions": [{"q": "Wie oft findet der Kurs pro Woche statt?", "options": ["Einmal", "Zweimal", "Dreimal"], "answer": 1, "why": "The course meets on Monday and Wednesday."}, {"q": "Was ist nicht im Preis enthalten?", "options": ["Der Einstufungstest", "Der Unterricht", "Das Lehrbuch"], "answer": 2, "why": "The textbook costs extra."}, {"q": "Was soll man vor der Kursanmeldung machen?", "options": ["Einen Einstufungstest", "Ein Buch schreiben", "Einen Termin beim Arzt"], "answer": 0, "why": "The placement test comes before registration."}]}, {"title": "Making weekend plans", "cat": "Listening", "group": "Leisure", "rule": "Listen for the original plan and the change. Informal messages often explain both a reason and an alternative.", "example": "Hallo Ben, hier ist Mia. Eigentlich wollten wir am Samstag wandern gehen. Leider soll es den ganzen Tag stark regnen. Wie wäre es stattdessen mit dem Technikmuseum? Dort gibt es gerade eine Ausstellung über erneuerbare Energie. Ich habe nachgesehen: Der Eintritt kostet zwölf Euro, aber mit einem Studierendenausweis nur acht. Wir könnten uns um halb elf vor dem Eingang treffen. Sag mir bitte bis heute Abend Bescheid, ob du mitkommst.", "translation": "Mia suggests the technology museum instead of hiking because heavy rain is forecast. Tickets are €12 or €8 for students. She proposes meeting at 10:30 and asks for a reply this evening.", "questions": [{"q": "Warum wird die Wanderung abgesagt?", "options": ["Ben muss arbeiten.", "Es soll stark regnen.", "Mia ist krank."], "answer": 1, "why": "Heavy rain is forecast for the whole day."}, {"q": "Was bezahlen Studierende mit Ausweis?", "options": ["8 Euro", "12 Euro", "Nichts"], "answer": 0, "why": "The discounted price is acht Euro."}, {"q": "Wann möchte Mia Ben treffen?", "options": ["11:30", "11:00", "10:30"], "answer": 2, "why": "Halb elf means 10:30."}]}], "vocab": [["die Bewerbung, -en", "job application", "Ich habe meine Bewerbung abgeschickt.", "Work"], ["die Erfahrung, -en", "experience", "Ich habe Erfahrung im Verkauf.", "Work"], ["sich bewerben um (+ Akk.)", "to apply for", "Ich bewerbe mich um eine Stelle.", "Work"], ["der Termin, -e", "appointment", "Ich möchte einen Termin vereinbaren.", "Health"], ["verschieben", "to reschedule", "Können wir den Termin verschieben?", "Health"], ["die Überweisung, -en", "bank transfer; medical referral", "Die Ärztin gibt mir eine Überweisung.", "Health"], ["die Nebenkosten (Pl.)", "additional housing costs", "Sind die Nebenkosten im Preis enthalten?", "Housing"], ["der Mietvertrag, -verträge", "rental agreement", "Ich unterschreibe den Mietvertrag.", "Housing"], ["sich kümmern um (+ Akk.)", "to take care of", "Ich kümmere mich um die Anmeldung.", "Everyday life"], ["zuverlässig", "reliable", "Meine Kollegin ist sehr zuverlässig.", "Work"], ["die Voraussetzung, -en", "prerequisite", "Welche Voraussetzungen gibt es?", "Education"], ["vereinbaren", "to arrange", "Wir vereinbaren einen neuen Termin.", "Everyday life"], ["die Verspätung, -en", "delay", "Der Zug hat zwanzig Minuten Verspätung.", "Travel"], ["umsteigen", "to change trains/buses", "In Bern müssen wir umsteigen.", "Travel"], ["die Entscheidung, -en", "decision", "Das ist eine wichtige Entscheidung.", "Everyday life"], ["sich entscheiden für (+ Akk.)", "to decide on", "Ich entscheide mich für den Abendkurs.", "Everyday life"], ["die Umwelt", "environment", "Wir möchten die Umwelt schützen.", "Environment"], ["vermeiden", "to avoid", "Ich versuche, Plastik zu vermeiden.", "Environment"], ["die Beschwerde, -n", "complaint", "Ich möchte eine Beschwerde schreiben.", "Everyday life"], ["trotzdem", "nevertheless", "Es regnet. Trotzdem gehen wir hinaus.", "Everyday life"], ["die Stelle, -n", "job position", "Ich suche eine feste Stelle.", "Work"], ["das Vorstellungsgespräch, -e", "job interview", "Morgen habe ich ein Vorstellungsgespräch.", "Work"], ["der Lebenslauf, -läufe", "CV / résumé", "Bitte schicken Sie Ihren Lebenslauf.", "Work"], ["die Ausbildung, -en", "vocational training", "Er macht eine Ausbildung zum Koch.", "Work"], ["die Kündigung, -en", "termination / notice", "Die Kündigung muss schriftlich sein.", "Work"], ["der Handwerker, -", "tradesperson (male)", "Der Handwerker repariert die Heizung.", "Housing"], ["die Kaution, -en", "deposit", "Die Kaution beträgt zwei Monatsmieten.", "Housing"], ["die Heizung, -en", "heating system", "Unsere Heizung funktioniert nicht.", "Housing"], ["der Umzug, -züge", "move / relocation", "Der Umzug ist am Samstag.", "Housing"], ["der Haushalt, -e", "household", "Wir teilen die Aufgaben im Haushalt.", "Housing"], ["die Untersuchung, -en", "medical examination", "Die Untersuchung dauert zwanzig Minuten.", "Health"], ["das Rezept, -e", "prescription; recipe", "Ich brauche ein Rezept für das Medikament.", "Health"], ["die Sprechstunde, -n", "consultation hours", "Die Sprechstunde beginnt um acht.", "Health"], ["die Beschwerden (Pl.)", "symptoms / discomfort", "Seit wann haben Sie diese Beschwerden?", "Health"], ["sich erholen", "to recover / relax", "Nach der Krankheit muss ich mich erholen.", "Health"], ["der Anschluss, -schlüsse", "connection", "Ich habe meinen Anschluss verpasst.", "Travel"], ["der Bahnsteig, -e", "platform", "Wir warten am Bahnsteig.", "Travel"], ["die Unterkunft, -künfte", "accommodation", "Wir suchen eine günstige Unterkunft.", "Travel"], ["die Rückfahrt, -en", "return journey", "Wann ist die Rückfahrt?", "Travel"], ["die Ermäßigung, -en", "discount / reduction", "Gibt es eine Ermäßigung für Studierende?", "Travel"]]};
const {lessons,vocab}=DATA;let memory={};let storageOK=true;try{memory=JSON.parse(localStorage.getItem('klar-b1')||'{}')}catch{storageOK=false}let state=memory&&typeof memory==='object'&&!Array.isArray(memory)?memory:{};state.scores=state.scores||{};state.scoreTotals=state.scoreTotals||{};state.known=Array.isArray(state.known)?state.known:[];let section='Exam home',current=-1,word=0,revealed=false;
const main=document.getElementById('main');const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem('klar-b1',JSON.stringify(state))}catch{storageOK=false}updateNav()}
function scoreLabel(i){if(state.scores[i]==null)return "Not started";const total=state.scoreTotals[i]||3;return total<lessons[i].questions.length?`Earlier edition: ${state.scores[i]}/${total} · new questions available`:`Best: ${state.scores[i]}/${total}`}
function complete(i){return state.scores[i]===lessons[i].questions.length}
function updateNav(){
 const names=['Exam home','Study plan','Exam practice','Exam writing','Speaking','Mock companion','My mistakes','Resources','Grammar practice','Home','Grammar','Vocabulary','Reading','Listening','Writing school','Writing','Mixed practice','Contents','My progress'];
 document.getElementById('nav').innerHTML=names.map(n=>`<button class="${section===n?'active':''}" ${section===n?'aria-current="page"':''} data-click="go" data-value="${n}">${n==='Home'?'Language library':n}</button>`).join('');
 const n=lessons.filter((_,i)=>complete(i)).length;
 document.getElementById('sideprogress').style.width=n/lessons.length*100+'%';
 document.getElementById('sidecount').textContent=`${n} / ${lessons.length} lessons mastered`;
 document.getElementById('storageNote').textContent=storageOK?'Saved on this device. Export a backup in My progress.':'Storage unavailable: progress lasts for this session.';
}
function foot(){return '<footer>Klar Deutsch · Original B1-focused learning material with core revision. Not a complete B1 course or official exam. Not affiliated with Lingolia. Independent telc B1 preparation; not endorsed by telc or Lingolia. Original tasks are not calibrated mock tests. Written content works offline; speech availability depends on your device.</footer>'}
function go(n){clearExamClock();document.querySelectorAll('audio').forEach(a=>a.pause());if('speechSynthesis'in window)speechSynthesis.cancel();section=n;current=-1;
updateNav();render();window.scrollTo(0,0)}
function cards(list){return `<div class="grid lesson-cards">${list.map(l=>{let i=lessons.indexOf(l);return `<button class="card" data-title="${esc(l.title.toLowerCase())}" data-click="lesson" data-value="${i}"><span class="num">${String(i+1).padStart(2,'0')}</span> <span class="pill">${l.cat}</span><h3>${esc(l.title)}</h3><p>${esc(l.rule.split('. ')[0])}.</p><div class="card-foot"><span>${complete(i)?'✓ Mastered':state.scores[i]!=null?scoreLabel(i):l.questions.length+' practice questions · learn at your pace'}</span><span>Open lesson ↗</span></div></button>`}).join('')}</div>`}
function render(){
 if(section==='Exam home')renderExamHome();
 else if(section==='Study plan')renderStudyPlan();
 else if(section==='Exam practice')renderExamPractice();
 else if(section==='Exam writing')renderExamWriting();
 else if(section==='Speaking')renderSpeaking();
 else if(section==='Mock companion')renderMockCompanion();
 else if(section==='My mistakes')renderMistakes();
 else if(section==='Resources')renderResources();
 else if(section==='Grammar practice')renderGrammarPractice();
 else if(section==='Home')renderHome();
 else if(['Grammar','Reading','Listening','Writing school','Vocabulary practice'].includes(section))renderCatalog(section);
 else if(section==='Vocabulary')renderVocabularyHome();
 else if(section==='Writing')renderWriting();
 else if(section==='Contents')renderContents();
 else if(section==='Mixed practice')renderMixed();
 else renderProgress();
 main.insertAdjacentHTML('beforeend',foot());
}
