 main.innerHTML=`<span class="eyebrow">Learning library · B1</span><h1>${esc(cat)}</h1><p class="small">${cat==='Grammar'?'Choose a grammar family, learn the rule, then practise with answer explanations. Core revision is included alongside B1 structures.':cat==='Listening'?'Original practical messages with browser-generated speech, German transcripts and English summaries. Offline audio needs an installed German voice.':'Read the explanation or text, answer the questions and check the evidence behind each answer.'}</p>${cat==='Grammar'?'<div class="callout"><b>More grammar practice</b><p>Try 12 worksheets with 144 questions, including 48 dative questions.</p><button data-click="go" data-value="Grammar practice">Open the workbook →</button></div>':''}<input class="search" id="catalogSearch" aria-label="Search topics" placeholder="Search this section…" data-input="filterCatalog"><div class="filter-row"><button data-click="group" data-value="">All topics</button>${groups.map((g,i)=>`<button data-click="group" data-value="${i}">${esc(g)}</button>`).join('')}</div><div id="catalog">${groups.map(g=>`<section class="catalog-group" data-group="${esc(g.toLowerCase())}"><h2>${esc(g)}</h2>${cards(list.filter(l=>l.group===g))}</section>`).join('')}</div><p id="empty" hidden>No matching topics. Try another search.</p>`;
