function selectGroup(i){const groups=[...new Set(lessons.filter(l=>l.cat===section).map(l=>l.group))];const input=document.getElementById('catalogSearch');input.value=i===''?'':groups[i];filterCatalog(input.value)}
function filterCatalog(value){const needle=value.toLowerCase();let total=0;document.querySelectorAll('.catalog-group').forEach(group=>{let count=0;group.querySelectorAll('.card').forEach(card=>{const show=group.dataset.group.includes(needle)||card.dataset.title.includes(needle);card.hidden=!show;if(show)count++});group.hidden=count===0;total+=count});document.getElementById('empty').hidden=total>0}
